582	
583	        // Panel was already confirmed open by the pre-capture check above.
584	        _metrics.InterfaceDetected = true;
585	
586	        using (_perf.Measure(OcrPerfTiming.Slot.FrameHash))
587	        {
588	            if (TrySkipOcrViaFrameDifferencing(capturedBitmap, options))
589	            {
590	                attemptedRecognition = true;
591	                fromCache = true;
592	                _runContext = _runContext with { RowYPositions = _lastOcrRowYPositions };
593	                _perf.RecordEnd(OcrPerfTiming.Slot.Total, t0);
594	                _perf.RecordEnd(OcrPerfTiming.Slot.CacheHit, t0);
595	                var totalMs = Stopwatch.GetElapsedTime(t0).TotalMilliseconds;
596	                _metrics.RecordCycle(totalMs, fromCache: true, isFullOcr: false);
597	                _metrics.CaptureMethod = _runContext.CaptureMethod;
598	                _metrics.IsPoe2Foreground = true;
599	                _metrics.InterfaceDetected = true;
600	                // Record per-cycle slot data so the breakdown stays in sync with Avg Duration
601	                var cacheCycleSlots = _perf.GetCycleSlotMs();
602	                for (var s = 0; s < cacheCycleSlots.Length; s++)
603	                    _metrics.RecordSlotDuration(s, cacheCycleSlots[s]);
604	                TryLogPerfMetrics(options);
605	                return _lastOcrText;
606	            }
607	        }
608	
609	        var debugContext = options.SaveDebugImages
610	            ? TryStartDebugCapture(capturedBitmap, region, captureMethod)
611	            : null;
612	
613	        attemptedRecognition = true;
614	        Bitmap preprocessed = null!;
615	        Bitmap? masked = null;
616	        try
617	        {
618	            using (_perf.Measure(OcrPerfTiming.Slot.KeepBlack))
619	                masked = OcrImagePreprocessor.KeepBlackAndNeighbors(capturedBitmap, _logger);
620	            using (_perf.Measure(OcrPerfTiming.Slot.Preprocess))
621	                preprocessed = OcrImagePreprocessor.PreprocessForOcr(masked, options, _logger);
622	            _logger.LogTrace("GDI: disposing old preprocessed bitmap");
623	            _lastPreprocessedBitmap?.Dispose();
624	            _logger.LogTrace("GDI: cloning preprocessed bitmap");
625	            _lastPreprocessedBitmap = new Bitmap(preprocessed);
626	            _logger.LogTrace("GDI: preprocessed clone OK");
627	
628	            // Extract pixel bytes ONCE and pass to downstream methods so they don't
629	            // need to call LockBits (which triggers MetaDataGetDispenser COM interop
630	            // and crashes). FindContentBounds and DetectRowPositions each called
